package com.htttdn.crm.web;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.stereotype.*; import org.springframework.web.filter.OncePerRequestFilter; import java.io.*;
@Component public class AdminAccessGuard extends OncePerRequestFilter { @Value("${app.admin.guard-enabled:false}") boolean enabled; protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException { if(enabled && r.getRequestURI().startsWith("/api/admin") && !"ADMIN".equals(r.getHeader("X-User-Role"))){s.setStatus(403);s.setContentType("application/json");s.getWriter().print("{\"code\":\"ADMIN_REQUIRED\",\"message\":\"Admin role required\"}");return;} c.doFilter(r,s); } }
